INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('b1cf4a5b21b0fb0763cb35b466bc1c2a14599942a7ac8ba36daa7704d61e94e3', 'en', 'ml', 'പ്രായത്തിനനുസരിച്ച് വായ ആരോഗ്യമുള്ളതാണ്. അടിയന്തര പ്രശ്നമൊന്നും കാണുന്നില്ല.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('8202d00c4dd3345693674e8b07719fc52a5d7fc3787853e4b0531cc26b523424', 'en', 'ml', 'മൃദുവായ ബ്രഷും ഫ്ലൂറൈഡ് ടൂത്ത്പേസ്റ്റും ഉപയോഗിച്ച് ദിവസം രണ്ടുനേരം പല്ല് തേക്കുക. ദിവസവും നാവ് വൃത്തിയാക്കുക.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('4c3fb426c07356740f924e1d31d6e2cbf66ecccb748136d83ecde689edb9e783', 'en', 'ml', '12 മാസത്തിനുശേഷം സാധാരണ പരിശോധന.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('8ee6d18f3d1e699bbdb2204f8525d0fbc13a216ff0c87decd037b93d8bd2c5c5', 'en', 'ml', 'പിന്നിലെ ചില പല്ലുകളിൽ കേടും താഴെ വലതുവശത്ത് ഒരു പൊട്ടിയ വേരും ഉണ്ട്.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('1faae48096d692f24dcd08a8ae177618bcdcca7d8cc61765de64980b5ef4433d', 'en', 'ml', 'ഭക്ഷണത്തിനിടയിൽ മധുരമുള്ള ചായയും പലഹാരങ്ങളും ഒഴിവാക്കുക. ദിവസം രണ്ടുനേരം ഫ്ലൂറൈഡ് ടൂത്ത്പേസ്റ്റ് ഉപയോഗിക്കുക.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('c836f14af6bfe33a8df5a300029d06ab5e5b5374104d9995a750bfcaa1b8ea3a', 'en', 'ml', 'ദന്ത ക്ലിനിക്കിൽ പല്ല് അടയ്ക്കലും പൊട്ടിയ വേര് എടുത്തുമാറ്റലും.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('79b69ffd209cbcdeeb39178f1218d88e65676712f524fefeed74019b3217ef29', 'en', 'ml', 'താഴത്തെ പല്ല്സെറ്റ് ഇളകുന്നു; അതിനടിയിൽ ഒരു വ്രണമുണ്ട്.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('663c3cbfe412ddb4cbffa0968a4c6d112c68653d5653ab8749dcd9f3071b02e1', 'en', 'ml', 'രാത്രി പല്ല്സെറ്റ് ഊരിവച്ച് ബ്രഷും വെള്ളവും ഉപയോഗിച്ച് വൃത്തിയാക്കുക. വ്രണത്തിന് വേദനയുള്ളപ്പോൾ ഇത് ഉപയോഗിക്കരുത്.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('d7d4413356b8c0f49cb1642e15b423a2cd4a9e22c3cebf2a48f3e9892d8adb0d', 'en', 'ml', 'ഡെന്റൽ കോളേജിൽ പുതിയ താഴത്തെ പല്ല്സെറ്റ് അല്ലെങ്കിൽ റീലൈൻ.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('64c73d1e627eca6f6d5148696793c157d55a60e6d5936c9ddf685449ee5b4856', 'en', 'ml', 'കക്കയും മോണയിൽ നിന്നുള്ള രക്തസ്രാവവുമുള്ള മോണരോഗം. രണ്ട് പല്ലുകൾ ഇളകുന്നു.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('36726a5f39fdc83e610678924c437fb44da1223202ab902285faa2850a38912b', 'en', 'ml', 'മോണയുടെ അരികുൾപ്പെടെ ദിവസം രണ്ടുനേരം മൃദുവായി ബ്രഷ് ചെയ്യുക. ചെറുചൂടുള്ള ഉപ്പുവെള്ളം കൊണ്ട് വായ കഴുകുക.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('8f396212e0ad950ccb3aa99255af33f4e080d8fb9455305a16a24c31805d4ed6', 'en', 'ml', 'ദന്ത ക്ലിനിക്കിൽ ക്ലീനിംഗും (സ്കെയിലിംഗ്) മോണ ചികിത്സയും.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('77cc29cb8f14988c0371559e366a5489aec3208a5da3cf63f64502fef00b8239', 'en', 'ml', 'കാൻസർ അല്ലെന്ന് ഉറപ്പാക്കാൻ വിദഗ്ധ പരിശോധന ആവശ്യമുള്ള വ്രണം അല്ലെങ്കിൽ പാട്.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('850e93e404e968542c361f492ea6a6ece412cce94d7f3061d79875b2b46b3d90', 'en', 'ml', 'പുകയിലയും അടയ്ക്കയും നിർത്തുക. ഒരാഴ്ചയ്ക്കുള്ളിൽ പരിശോധനയ്ക്ക് പോകുക.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('cc95eb2497d67348e75323833230fc8936d012c39cda5d7001c84efe3a81c861', 'en', 'ml', 'ഓറൽ മെഡിസിൻ വിഭാഗത്തിൽ പരിശോധന; ആവശ്യമെങ്കിൽ ബയോപ്സി.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('0b3fdcfae2f3cb64a9de5e3a836ec512c896b2b7608e8a52162b8ba258408262', 'en', 'ml', 'മരുന്നുകൾ കാരണമാകാവുന്ന വായ് വരൾച്ച; മോണയുടെ അരികിൽ തുടക്കത്തിലുള്ള കേട്.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('6da5ae448030b38398ae513f22d1f66f4a152e92e9585bf53be057574ee0900c', 'en', 'ml', 'ഇടയ്ക്കിടെ കുറേശ്ശെ വെള്ളം കുടിക്കുക. ഭക്ഷണത്തിനിടയിൽ ഉണങ്ങിയ പലഹാരങ്ങൾ ഒഴിവാക്കുക. ഫ്ലൂറൈഡ് ടൂത്ത്പേസ്റ്റ് ഉപയോഗിക്കുക.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('039e60d013bfdd38ba5eae62aed18df68bf7a0455cbbf9e123cbec7a45364275', 'en', 'ml', 'ഏതെങ്കിലും മരുന്ന് മാറ്റാനാകുമോ എന്ന് ഡോക്ടറോട് ചോദിക്കുക. 6 മാസത്തിനുശേഷം ദന്ത പരിശോധന.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('4e60d307734d9819ba3255e16846645f8e408dbaaea1f16d6e23ad6c444ba6d7', 'en', 'ml', 'കിടപ്പിലായ വ്യക്തി; പല്ലിൽ പ്ലാക്കും നാവിൽ ആവരണവും.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('2dfee2f41432bbac7b618f1276549ca1d1f349196d5c3e92ec2029033dc5b770', 'en', 'ml', 'വ്യക്തിയെ ഇരുത്തിയശേഷം പരിചാരകർ ദിവസം രണ്ടുനേരം മൃദുവായ ബ്രഷ് കൊണ്ട് പല്ലും നാവും വൃത്തിയാക്കണം.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('3b00936b31d21e6114b5a1d4700ed78bcd19f2d7b9082413e2b88204599f1fa4', 'en', 'ml', 'വൃത്തിയാക്കലിനായി വീട്ടിലെത്തിയുള്ള ദന്ത പരിശോധന.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('f12a59211a337be6967762762a1b69b26550d990416a03fea6e53c84645fc87a', 'ml', 'en', 'The lower denture is loose. Small sore on the gum.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('509f971b7502cb9c5a4cf5c447840e9142c25e1dfaf016ac3f10a26cb057f989', 'ml', 'en', 'Remove the denture at night. Do not use it until the sore heals.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('7ef44098bfe64cb5ecd774772e3fa4989e55c2a2e0b443b1ae4b38a14b58cef6', 'ml', 'en', 'Get a reline done at the dental college.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('37b58910a0d871a313ed7076c210479c4b4d037823d35a59a5f8ef79b686a25f', 'ml', 'en', 'The lower denture is loose; cannot chew.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('59860413ce66109e0f767ac37955892b34f36e39a2b86dc80870bb6da6219716', 'ml', 'en', 'Tooth pain on the lower right side; cannot sleep at night.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('b0866377e14f61721053e9ffda5d7dde6b487c2396d084cc96f1d807f23c1815', 'ml', 'en', 'A sore on the side of the tongue that has not healed for a month.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('8e1eb48741695734c50e9a38d30916fe45e8ad44d767c32b2dac308dff6874a5', 'ml', 'en', 'Gums bleed when brushing.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('0fd2f5d3cface235ea51e336c05e09a1d28bb85ed66628a3ce0499a16a9c5f72', 'ml', 'en', 'Mouth is always dry; difficulty swallowing food.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('4ba3196688049f576f9189ac4682e7cc6226576f7004d259374f53ca221859db', 'ml', 'en', 'Most teeth are gone; would like a denture.', 'demo-reviewed');
INSERT OR REPLACE INTO translations (hash, src_lang, tgt_lang, out_text, engine) VALUES ('796644b9c63ba9e2fcd67625230e747d2053fb7103dac2aeffa141538465bc7f', 'ta', 'en', 'The lower denture is loose; cannot eat.', 'demo-reviewed');
